// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzzed params: amount to send and an initial deposit to make attacker have balance
    function testFuzz_property(uint256 sendAmount, uint256 initialDeposit) public {
        // keep amounts in reasonable bounds and non-zero for meaningful tests
        sendAmount = bound(sendAmount, 1, 10 ether);
        initialDeposit = bound(initialDeposit, 0, 10 ether);

        // deploy attacker helper that will reenter in its receive
        Attacker atk = new Attacker(address(c));

        // fund attacker externally so it can call Put with value
        vm.deal(address(atk), sendAmount + initialDeposit + 1 ether);

        // make attacker deposit an initialDeposit into its account first via Put
        if (initialDeposit > 0) {
            vm.prank(address(atk));
            // call Put with initialDeposit
            atk.callPut{value: initialDeposit}(0);
        }

        // record balance before the critical Put
        (uint unlockBefore, uint balBefore) = c.Acc(address(atk));

        // Now perform the Put that will trigger attacker's reentrancy during LogFile.AddMessage
        // Attacker's fallback will reenter and attempt to Collect some amount, trying to change its balance
        vm.prank(address(atk));
        // call Put with sendAmount which in the buggy mutant (no nonReentrant) allows reentrancy to alter balance
        atk.callPut{value: sendAmount}(0);

        // After Put completes, reference contract invariant: Acc[atk].balance == balBefore + sendAmount
        (uint unlockAfter, uint balAfter) = c.Acc(address(atk));

        // single assertion reading c's public getter to express the invariant
        assertTrue(balAfter == balBefore + sendAmount);
    }
}

// minimal re-entrant attacker: when receiving Ether during Put (via the Log call), reenter Collect
contract Attacker {
    C target;
    constructor(address _t) payable { target = C(_t); }

    // helper to call Put on target
    function callPut(uint _unlockTime) external payable {
        target.Put{value: msg.value}(_unlockTime);
    }

    // receive will attempt to reenter Collect to withdraw funds during the vulnerable window
    receive() external payable {
        // attempt to withdraw a small amount if we have any balance; ignore failures
        uint toWithdraw = 1 ether / 10; // small withdrawal attempt
        // try/catch to avoid bubbling revert to the original call
        try target.Collect(toWithdraw) {
        } catch {
        }
    }
}

