    // We will deploy an Attacker helper that is able to reenter via Collect during Put by relying on the buggy modifier.
    function testFuzz_property(uint256 initBal, uint256 deposit) public {
        // keep values in wide but practical ranges
        initBal = bound(initBal, 0, 10 ether);
