        Attacker attacker = new Attacker(address(c));
        address attackerAddr = address(attacker);

        // fund attacker externally so it can send deposit
        vm.deal(attackerAddr, deposit + 1 ether);

        // Ensure attacker has an existing entry in Acc with some balance so reentrant Collect can succeed
        // We make the attacker do an initial Put for initBal (if initBal>0). Use attacker to call Put with initBal.
        if (initBal > 0) {
            vm.prank(attackerAddr);
            c.Put{value: initBal}(block.timestamp);
