        // Record previous stored balance for attacker
        uint256 before = c.Acc(attackerAddr).balance;

        // Now instruct attacker helper to perform Put(deposit) which during execution will attempt to reenter Collect
        // The attacker is designed to try reentrancy during the fallback when receiving Ether. For the reference contract
