    // params: depositor address (must be this), deposit amount, withdraw amount, unlock time in future
    function run(uint depositAmt, uint withdrawAmt, uint unlockTime) public {
        // preconditions for meaningful scenario
        require(depositAmt >= 1 wei);
        require(address(this).balance >= depositAmt);
        // Make a deposit via Put: this increases Acc[this].balance and sets unlockTime
        c.Put{value: depositAmt}(unlockTime);

        // Ensure conditions for Collect: deposit must be >= MinSum and >= withdrawAmt
        // Read MinSum from contract
        uint min = c.MinSum();
        require(depositAmt >= min);
