        // on mutant M the contract remains locked and this call will revert / fail.
        // We observe success by calling it and catching reversion via low-level call return value.
        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, withdrawAmt));

        // The distinguishing assertion: the second Collect should succeed (ok == true).
        // On P this holds for all inputs satisfying the requires above; on M it will be false because the contract stays locked.
        assert(ok == true);
    }

    // Allow contract to receive ETH for deposit payments
    receive() external payable {}
}

